import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.DDY-poMm.js";const p=JSON.parse('{"title":"System Components","description":"","frontmatter":{},"headers":[],"relativePath":"intro/components.md","filePath":"intro/components.md","lastUpdated":1791353800000}'),o={name:"intro/components.md"};function r(i,e,d,l,c,m){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="system-components" tabindex="-1">System Components <a class="header-anchor" href="#system-components" aria-label="Permalink to &quot;System Components&quot;">​</a></h1><p>The system consists of <strong>six parts</strong>: two internal management portals, two web front ends for end users, a native mobile app, and BTX Wallet, a self-custody Web3 wallet.</p><h2 id="responsibilities" tabindex="-1">Responsibilities <a class="header-anchor" href="#responsibilities" aria-label="Permalink to &quot;Responsibilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>Used by</th><th>Main purpose</th></tr></thead><tbody><tr><td><strong>Admin console</strong></td><td>Platform operations, finance, customer service</td><td>The most complete part: user management, KYC review, deposit and withdrawal review, ledger, coins and trading pairs, feature toggles, site configuration, dashboards</td></tr><tr><td><strong>Market maker portal</strong></td><td>Project teams / market makers</td><td>Checking orders and trades</td></tr><tr><td><strong>User PC site</strong></td><td>End users</td><td>The web trading platform, with full market data, spot and contract trading screens and account center</td></tr><tr><td><strong>User mobile H5 site</strong></td><td>End users</td><td>Mobile site accessed from a phone browser, feature-aligned with the PC site</td></tr><tr><td><strong>Native dual-platform app (Android / iOS)</strong></td><td>End users</td><td>A native app, not a web wrapper. See <a href="/CoinExchange/app/overview">App Overview</a></td></tr><tr><td><strong>BTX Wallet (Web3 wallet, private beta)</strong></td><td>End users</td><td>Self-custody wallet for trading tokenized US stocks on-chain. See <a href="/CoinExchange/app/wallet">BTX Wallet</a></td></tr></tbody></table><h2 id="user-side-features" tabindex="-1">User-side features <a class="header-anchor" href="#user-side-features" aria-label="Permalink to &quot;User-side features&quot;">​</a></h2><p>The PC site and mobile H5 site serve the same users and are feature-aligned:</p><ul><li><strong>Markets</strong>: coin list, candlestick charts, real-time quotes</li><li><strong>Trading</strong>: spot, instant swap, seconds contracts, USDT-margined contracts, TradFi instruments</li><li><strong>Assets</strong>: deposits, withdrawals, transfers, statements</li><li><strong>Wealth</strong>: wealth management, staking, assisted lending, token subscription</li><li><strong>Account</strong>: sign-up and login, KYC, security settings (login password / fund password / email / Google Authenticator), referrals</li><li><strong>Other</strong>: help center, announcements, live chat, language switching</li></ul><h2 id="admin-console-modules" tabindex="-1">Admin console modules <a class="header-anchor" href="#admin-console-modules" aria-label="Permalink to &quot;Admin console modules&quot;">​</a></h2><ul><li><strong>System management</strong>: admin accounts, roles and permissions, menus, dictionaries, announcements, help center</li><li><strong>Business management</strong>: users, assets, bank cards, KYC, deposits, withdrawals, fund sweeping, commissions, ledger, coins and trading pairs, geo-restrictions</li><li><strong>Trading and products</strong>: spot, USDT-margined contracts, seconds contracts, assisted lending, staking, token subscription, wealth management, copy trading</li><li><strong>Configuration center</strong>: site configuration (see <a href="/CoinExchange/guide/site-config">Site Configuration</a>), payment gateways, SMS and email, <a href="/CoinExchange/guide/customer-service">Customer Service</a> (Telegram-based)</li><li><strong>Dashboards</strong>: platform operating statistics</li></ul><h2 id="technology" tabindex="-1">Technology <a class="header-anchor" href="#technology" aria-label="Permalink to &quot;Technology&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">For technical evaluation</p><ul><li>Backend: Java (Spring Boot), with two services — a management service for the admin console and a business service for end users</li><li>Front end: Vue stack, four independent projects</li><li>Mobile: native Flutter app (Android / iOS)</li><li>Data storage: MySQL + Redis</li><li>Real-time market data: WebSocket push</li></ul></div><p>For deployment requirements, server specifications and operations plans, please contact us for the deployment documentation.</p>',12)])])}const u=t(o,[["render",r]]);export{p as __pageData,u as default};
